#' Horizontal Box-Violin Comparison
#'
#' Compares a continuous variable across groups and draws the comparison
#' horizontally - values on the x axis, group labels down the y axis - with
#' an optional vertical reference line. Wraps ggstatsplot::ggbetweenstats
#' and ggstatsplot::grouped_ggbetweenstats, so the figure is a box-violin
#' plot with the individual observations shown, and the test is a
#' between-groups comparison using every observation.
#' 
#' This analysis was previously titled "Dot Chart", which described neither
#' the figure nor the statistic: it draws violins and boxplots, not a dot
#' chart, and it is a between-groups test rather than a one-sample one. For
#' a genuine Cleveland dot chart - one summary point per label, tested
#' against a reference value - use "Dot Chart (Summary vs Reference Value)",
#' which wraps ggstatsplot::ggdotplotstats.
#' 
#' Prefer this over "Box-Violin Plots to Compare Between Groups" when the
#' group labels are long or numerous, since the horizontal layout gives them
#' room, or when a clinical threshold line is useful.
#' 
#' @param data The data as a data frame.
#' @param dep A continuous numeric variable for which the distribution will be
#'   displayed across different groups using dot plots.
#' @param group A categorical variable that defines the groups for comparison.
#'   Each level will be displayed as a separate group in the dot plot.
#' @param grvar Optional grouping variable to create separate dot plots for
#'   each level of this variable (grouped analysis).
#' @param typestatistics Choose the appropriate statistical test: Parametric
#'   (t-test) assumes normal distribution and equal variances; Nonparametric
#'   (Mann-Whitney U) makes no distribution assumptions; Robust uses trimmed
#'   means to handle outliers; Bayesian provides evidence strength via Bayes
#'   factors.
#' @param effsizetype Effect size quantifies practical significance: Cohen's d
#'   shows standardized difference between groups (small=0.2, medium=0.5,
#'   large=0.8); Hedge's g corrects for small samples; Eta/Omega-squared show
#'   proportion of variance explained (small=0.01, medium=0.06, large=0.14).
#' @param centralityplotting Display lines showing the central tendency (mean,
#'   median, or trimmed mean) for each group. Helps visualize group differences
#'   at a glance.
#' @param centralitytype Type of central tendency to display: Mean is the
#'   average but sensitive to outliers; Median is the middle value and robust to
#'   outliers; Trimmed mean excludes extreme values; Bayesian provides
#'   probabilistic estimate.
#' @param mytitle Main title for the plot. Leave blank for automatic title
#'   generation based on your variables.
#' @param xtitle Label for the horizontal axis showing the continuous variable
#'   values. Leave blank to use variable name.
#' @param ytitle Label for the vertical axis showing the group categories.
#'   Leave blank to use variable name.
#' @param originaltheme Use the original ggstatsplot theme instead of jamovi's
#'   default theme. The original theme may be more suitable for publications.
#' @param resultssubtitle Display statistical test results (p-value, effect
#'   size, confidence interval) as a subtitle below the plot. Recommended for
#'   most analyses.
#' @param testvalue Position of the optional reference line, in the units of
#'   the dependent variable. Use it to mark a clinically meaningful threshold
#'   such as an upper limit of normal. No hypothesis test is performed against
#'   this value; it only draws a line, and only when 'Reference value line' is
#'   ticked.
#' @param bfmessage Display Bayes Factor interpretation (evidence strength)
#'   when using Bayesian analysis. BF > 3 indicates moderate evidence, BF > 10
#'   strong evidence.
#' @param conflevel Confidence level for intervals (0.95 = 95 percent
#'   confidence interval). This represents the probability that the true
#'   population parameter lies within the calculated interval. 95 percent is
#'   standard for most analyses.
#' @param k Number of decimal places for statistical results (p-values, effect
#'   sizes). More decimal places show greater precision but may not be
#'   clinically meaningful.
#' @param testvalueline Draw a dashed vertical line at 'Reference Line Value'.
#'   Useful for marking a clinical threshold or a normal reference limit. This
#'   is a visual annotation only.
#' @param centralityparameter Which central tendency measure to show as a
#'   vertical line on the plot. Mean is sensitive to outliers; median is more
#'   robust for skewed data.
#' @param centralityk Deprecated and ignored. The statistics package no longer
#'   accepts a separate precision for the centrality labels; they follow
#'   'Statistical Precision (Decimal Places)'. Retained so existing scripts keep
#'   running, and removed from the user interface.
#' @param plotwidth Width of the plot in pixels. Larger values provide more
#'   detail but may not fit well in reports. Default: 650 pixels.
#' @param plotheight Height of the plot in pixels. Adjust based on number of
#'   groups to ensure readability. Default: 450 pixels.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notices} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot2} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
jjdotplotstats <- function(
    data,
    dep,
    group,
    grvar = NULL,
    typestatistics = "parametric",
    effsizetype = "biased",
    centralityplotting = FALSE,
    centralitytype = "parametric",
    mytitle = "",
    xtitle = "",
    ytitle = "",
    originaltheme = FALSE,
    resultssubtitle = FALSE,
    testvalue = 0,
    bfmessage = FALSE,
    conflevel = 0.95,
    k = 2,
    testvalueline = FALSE,
    centralityparameter = "mean",
    centralityk = 2,
    plotwidth = 650,
    plotheight = 450) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("jjdotplotstats requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(grvar)) grvar <- jmvcore::resolveQuo(jmvcore::enquo(grvar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(grvar), grvar, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in grvar) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- jjdotplotstatsOptions$new(
        dep = dep,
        group = group,
        grvar = grvar,
        typestatistics = typestatistics,
        effsizetype = effsizetype,
        centralityplotting = centralityplotting,
        centralitytype = centralitytype,
        mytitle = mytitle,
        xtitle = xtitle,
        ytitle = ytitle,
        originaltheme = originaltheme,
        resultssubtitle = resultssubtitle,
        testvalue = testvalue,
        bfmessage = bfmessage,
        conflevel = conflevel,
        k = k,
        testvalueline = testvalueline,
        centralityparameter = centralityparameter,
        centralityk = centralityk,
        plotwidth = plotwidth,
        plotheight = plotheight)

    analysis <- jjdotplotstatsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

